85	impl HooksContext {
86	    fn add(&mut self, hook_name: &str) -> u8 {
87	        let counter = match hook_name {
88	            "after" => &mut self.after,
89	            "afterAll" => &mut self.after_all,
90	            "afterEach" => &mut self.after_each,
91	            "before" => &mut self.before,
92	            "beforeEach" => &mut self.before_each,
93	            "beforeAll" => &mut self.before_all,
94	            _ => return 0, // Should never happen
95	        };
96	        if *counter <= 1 {
97	            *counter += 1;
98	        }
99	
100	        *counter
101	    }
102	}
