112	    fn visit(
113	        &mut self,
114	        event: &WalkEvent<SyntaxNode<Self::Language>>,
115	        mut ctx: VisitorContext<Self::Language>,
116	    ) {
117	        match event {
118	            WalkEvent::Enter(node) => {
119	                let Some(node) = JsCallExpression::cast_ref(node) else {
120	                    return;
121	                };
122	
123	                // When the visitor enters a function node, push a new entry on the stack
124	                if Self::is_test_describe_call(&node) {
125	                    self.stack.push(HooksContext::default());
126	                }
127	
128	                if let Ok(AnyJsExpression::JsIdentifierExpression(identifier)) = node.callee() {
129	                    identifier
130	                        .name()
131	                        .and_then(|name| name.value_token())
132	                        .map_or((), |name| {
133	                            if let Some(hooks_context) = self.stack.last_mut() {
134	                                match name.text_trimmed() {
135	                                    "beforeEach" | "beforeAll" | "afterEach" | "afterAll"
136	                                    | "after" | "before" => {
137	                                        let counter =
138	                                            HooksContext::add(hooks_context, name.text_trimmed());
139	                                        if counter > 1 {
140	                                            ctx.match_query(DuplicateHooks(node.clone()));
141	                                        }
142	                                    }
143	                                    _ => {}
144	                                };
145	                            };
146	                        })
147	                }
148	            }
149	            WalkEvent::Leave(node) => {
150	                // When the visitor exits a function, if it matches the node of the top-most
151	                // entry of the stack and the `has_yield` flag is `false`, emit a query match
152	                if let Some(node) = JsCallExpression::cast_ref(node)
153	                    && Self::is_test_describe_call(&node)
154	                {
155	                    self.stack.pop();
156	                }
157	            }
158	        }
159	    }
160	}
