162	impl DuplicateHooksVisitor {
163	    /// Determines if a [call expression] is a `describe.` call by checking:
164	    /// 1. The node must be a test call expression
165	    ///    e.g. `it.only`, `describe.skip`, `test`
166	    /// 2. The test call must be a `describe.` call
167	    ///    first section = `describe` | `fdescribe` | `xdescribe` e.g. `describe.only`, `describe.skip`
168	    ///    or second section = `describe` e.g. `test.describe`
169	    ///
170	    /// [call expression]: crate::JsCallExpression
171	    fn is_test_describe_call(node: &JsCallExpression) -> bool {
172	        if let Ok(callee) = node.callee()
173	            && node.is_test_call_expression() == Ok(true)
174	        {
175	            let text = callee.to_trimmed_text();
176	            let mut split = text.split('.');
177	
178	            let first = split.next();
179	            let second = split.next();
180	
181	            if matches!(first, Some("describe" | "fdescribe" | "xdescribe"))
182	                || second == Some("describe")
183	            {
184	                return true;
185	            }
186	        }
187	
188	        false
189	    }
190	}
