/// Tracks the titles seen so far within a single scope (a `describe` block or
/// the top level). Test titles and describe titles are tracked independently.
#[derive(Default)]
struct TitleScope {
    tests: FxHashSet<String>,
    describes: FxHashSet<String>,
}

struct IdenticalTitleVisitor {
    stack: Vec<TitleScope>,
}

impl Default for IdenticalTitleVisitor {
    fn default() -> Self {
        // Start with a scope representing the top level.
        Self {
            stack: vec![TitleScope::default()],
        }
    }
}

impl Visitor for IdenticalTitleVisitor {
