/// Determines whether a [call expression]'s callee is a `describe.` call, e.g.
/// `describe`, `describe.only`, `describe.skip`, `fdescribe`, `xdescribe`, or
/// `test.describe`.
///
/// [call expression]: biome_js_syntax::JsCallExpression
fn is_describe_call(callee: &AnyJsExpression) -> bool {
    let text = callee.to_trimmed_text();
    let mut split = text.split('.');

    let first = split.next();
    let second = split.next();

    matches!(first, Some("describe" | "fdescribe" | "xdescribe")) || second == Some("describe")
}

/// Extracts the static string title of a test/describe call, if any. Returns the
/// title text alongside the range of the title node. Returns `None` when the
/// title is missing or dynamic (e.g. a template literal with expressions).
fn get_static_title(call: &JsCallExpression) -> Option<(String, TextRange)> {
    let arguments = call.arguments().ok()?;
    let first = arguments.args().iter().next()?.ok()?;
    let expression = first.as_any_js_expression()?;

    match expression.as_static_value()? {
        value @ (StaticValue::String(_) | StaticValue::EmptyString(_)) => {
            Some((value.text().to_string(), expression.range()))
        }
        _ => None,
    }
}

